// 2^(k/4), k = 0..3, as 18-bit unsigned with 17 fraction bits.
module mp3_frac4 (
    input  logic [1:0]  k,
    output logic [17:0] v
);
    always_comb
        case (k)
            2'd0: v = 18'd131072;
            2'd1: v = 18'd155872;
            2'd2: v = 18'd185364;
            2'd3: v = 18'd220436;
        endcase
endmodule

// Coefficients, 18-bit signed with 17 fraction bits (as crates/mp3model/src/fixed.rs).
module mp3_coefs (
    input  logic [2:0]  aa_i,
    input  logic [2:0]  is_pos,
    output logic signed [17:0] aa_cs,
    output logic signed [17:0] aa_ca,
    output logic signed [17:0] ms,
    output logic signed [17:0] is_kl,
    output logic signed [17:0] is_kr
);
    assign ms = 18'sd92682;
    always_comb begin
        case (aa_i)
            3'd0: begin aa_cs = 18'sd112393; aa_ca = -18'sd67436; end
            3'd1: begin aa_cs = 18'sd115572; aa_ca = -18'sd61831; end
            3'd2: begin aa_cs = 18'sd124470; aa_ca = -18'sd41075; end
            3'd3: begin aa_cs = 18'sd128885; aa_ca = -18'sd23844; end
            3'd4: begin aa_cs = 18'sd130485; aa_ca = -18'sd12396; end
            3'd5: begin aa_cs = 18'sd130962; aa_ca = -18'sd5369; end
            3'd6: begin aa_cs = 18'sd131059; aa_ca = -18'sd1861; end
            3'd7: begin aa_cs = 18'sd131071; aa_ca = -18'sd485; end
            default: begin aa_cs = '0; aa_ca = '0; end
        endcase
        case (is_pos)
            3'd0: begin is_kl = 18'sd0; is_kr = 18'sd131071; end
            3'd1: begin is_kl = 18'sd27699; is_kr = 18'sd103373; end
            3'd2: begin is_kl = 18'sd47976; is_kr = 18'sd83096; end
            3'd3: begin is_kl = 18'sd65536; is_kr = 18'sd65536; end
            3'd4: begin is_kl = 18'sd83096; is_kr = 18'sd47976; end
            3'd5: begin is_kl = 18'sd103373; is_kr = 18'sd27699; end
            3'd6: begin is_kl = 18'sd131071; is_kr = 18'sd0; end
            default: begin is_kl = '0; is_kr = '0; end
        endcase
    end
endmodule
